solution.solution.cpp:
template <typename T>
class Counted
{
public:
    static int alive() { return s_alive; }

protected:
    Counted() { ++s_alive; }
    Counted(const Counted&) { ++s_alive; }
    Counted(Counted&&) noexcept { ++s_alive; }
    Counted& operator=(const Counted&) = default;
    Counted& operator=(Counted&&) noexcept = default;
    ~Counted() { --s_alive; }

private:
    static inline int s_alive{ 0 };
};

unitTests:
struct Enemy : Counted<Enemy> { Enemy() = default; int hp{ 10 }; };
struct Bullet : Counted<Bullet> { Bullet() = default; };
static_assert(!std::is_constructible_v<Counted<int>>, "the constructor should be protected");

TEST("each class has its own counter") {
    CHECK_EQ(Enemy::alive(), 0);
    CHECK_EQ(Bullet::alive(), 0);
    {
        Enemy a{}, b{};
        Bullet x{};
        CHECK_EQ(Enemy::alive(), 2);
        CHECK_EQ(Bullet::alive(), 1);
    }
    CHECK_EQ(Enemy::alive(), 0);
    CHECK_EQ(Bullet::alive(), 0);
}
TEST("copies and moves count as objects too") { Enemy a{}; Enemy b{ a }; Enemy c{ std::move(a) }; CHECK_EQ(Enemy::alive(), 3); b = c; CHECK_EQ(Enemy::alive(), 3); }
TEST("in a container") { { std::vector<Bullet> v(25); CHECK_EQ(Bullet::alive(), 25); v.resize(10); CHECK_EQ(Bullet::alive(), 10); } CHECK_EQ(Bullet::alive(), 0); }

